dtsPropsFor.CardThumb:
/** 카드 그림을 고르는 포스트 slug. CARD_MAP 에 없으면 slug 해시로 폴백한다 */
  slug: string;
  /** 크게(90px) 그릴지 — 목록 히어로용 */
  featured?: boolean;

dtsPropsFor.LegalPage:
eyebrow: React.ReactNode;
  title: string;
  lead: string;
  /** 최종 수정일 (YYYY-MM-DD) */
  updated: string;
  /** 조항 위에 놓이는 자유 블록. `.legal-prose` 밖에 렌더된다 */
  intro?: React.ReactNode;
  children?: React.ReactNode;

dtsPropsFor.LegalSection:
id: string;
  title: string;
  children?: React.ReactNode;

dtsPropsFor.RankingTable:
/** 표의 접근성 라벨 겸 제목 */
  name: string;
  items: { name: string; description?: string }[];
  /** 기본 Descending — 1위가 위 */
  order?: "Ascending" | "Descending";

dtsPropsFor.ReadingProgressBar:
/** 진행률을 잴 대상. 없으면 문서 전체 */
  targetRef?: React.RefObject<HTMLElement>;
  /** 아랍어 등 RTL 로케일에서 진행 방향을 뒤집는다 */
  rtl?: boolean;
